#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum BalanceError {
    Overflow,
}

impl std::fmt::Display for BalanceError {
    fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
        f.write_str("balance overflowed i64")
    }
}

impl std::error::Error for BalanceError {}

pub fn balance(entries: &[Entry]) -> Result<i64, BalanceError> {
    let mut total: i64 = 0;
    for e in entries {
        total = match e.kind {
            Kind::Credit => total.checked_add(e.amount_cents),
            Kind::Debit => total.checked_sub(e.amount_cents),
        }
        .ok_or(BalanceError::Overflow)?;
    }
    Ok(total)
}

